// Generates `src/i18n-messages.ts`: the English strings of
// `_locales/en/messages.json`, as the fallback `t()` uses when
// `chrome.i18n` isn't available (see src/i18n.ts), and the source of its
// typed key set.
//
// Run `npm run i18n` after changing `_locales/en/messages.json`; the
// generated file is committed, and a unit test fails when it's out of date.
//
// Chrome compiles a message's named `$PLACEHOLDER$` tokens down to the
// positional `$1`, `$2`, … of its `placeholders` block, and `$$` to a
// literal `$` - this does the same.

import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import prettier from 'prettier';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const src = path.join(root, '_locales', 'en', 'messages.json');
const dst = path.join(root, 'src', 'i18n-messages.ts');

const messages = JSON.parse(await readFile(src, 'utf8'));
const lines = Object.entries(messages).map(([key, entry]) => {
	const placeholders = Object.fromEntries(
		Object.entries(entry.placeholders ?? {}).map(([name, p]) => [name.toLowerCase(), p.content]),
	);
	const template = entry.message.replace(/\$([A-Za-z0-9_@]+)\$|\$\$/g, (token, name) => {
		if (token === '$$') return '$';
		const content = placeholders[name.toLowerCase()];
		if (content === undefined) throw new Error(`${key}: no placeholder named ${name}`);
		return content;
	});
	return `\t${key}: ${JSON.stringify(template)},`;
});

const code = `// Generated by scripts/build-i18n.js from _locales/en/messages.json - do not
// edit. Run \`npm run i18n\` after changing the English messages.

export const EN_MESSAGES = {
${lines.join('\n')}
} as const;
`;

const formatted = await prettier.format(code, { ...(await prettier.resolveConfig(dst)), filepath: dst });
await writeFile(dst, formatted);
console.log(`wrote ${path.relative(root, dst)} (${lines.length} messages)`);
